1	import { priceItems } from "./item-pricing.js";
2	import type { Customer, Item } from "./policy.js";
3	import { policyWideAdjustment } from "./policy-modifier.js";
4	
5	const PROCESSING_FEE = 5;
6	
7	/**
8	 * Item-specific modifiers apply to the base premium of the affected item;
9	 * policy-wide modifiers apply to the policy base premium; the processing
10	 * fee is added at the very end.
11	 *
12	 * Rounding is not an active behavior yet, so a premium may still come out
13	 * as a fraction.
14	 */
15	export function quote(
16	  customer: Customer,
17	  items: readonly Item[],
18	  previousContracts: number,
19	): number {
20	  const { basePremium, riskSurcharges } = priceItems(items);
21	
22	  return (
23	    basePremium +
24	    riskSurcharges +
25	    policyWideAdjustment({ customer, previousContracts }, basePremium) +
26	    PROCESSING_FEE
27	  );
28	}
