1	import { componentsBasePremium, isComponent } from "./component-block.js";
2	import { priceMainItems } from "./main-item.js";
3	import type { Item, ItemPricing } from "./policy.js";
4	
5	/**
6	 * Each item is priced by the pricing policy that governs its kind:
7	 * components may form blocks, main items follow the price list.
8	 * Components carry no item-specific risk surcharges.
9	 */
10	export function priceItems(items: readonly Item[]): ItemPricing {
11	  const mainItems = priceMainItems(items.filter((item) => !isComponent(item)));
12	  const componentsBase = componentsBasePremium(items.filter(isComponent));
13	
14	  return {
15	    basePremium: mainItems.basePremium + componentsBase,
16	    riskSurcharges: mainItems.riskSurcharges,
17	  };
18	}
