const PROCESSING_FEE = 5;

/**
 * The premium the MHPCO charges for a policy, before rounding.
 *
 * Item-specific modifiers have already been applied to the base premium of
 * the affected item; policy-wide modifiers scale the policy base premium;
 * the processing fee is added at the very end, so it is part of the amount
 * a later rounding rule would round.
 */
function assessedPremium(
  contract: Contract,
  pricing: ItemPricing,
): number {
  const { basePremium, riskSurcharges } = pricing;

  return (
    basePremium +
    riskSurcharges +
    policyWideAdjustment(contract, basePremium) +
    PROCESSING_FEE
  );
}

